// 根据用户签名选择 whispers
export function selectWhispers(
  userSignature: {
    top_3_ef: string[];
    top_3_domains: string[];
    primary_scenes: string[];
    qm_core: {
      inattention_mean: number;
      hyperactivity_mean: number;
      impulsivity_mean: number;
    };
  },
  count: number = 6
): WhisperUnit[] {
  const selected: WhisperUnit[] = [];
  const used = new Set<string>();

  // 策略：优先匹配用户最强的维度和场景
  const priorityTags = [
    ...userSignature.top_3_ef,
    ...(userSignature.primary_scenes?.slice(0, 3) || []),
    userSignature.qm_core.inattention_mean >= 2.5 ? 'inattention' : '',
    userSignature.qm_core.hyperactivity_mean >= 2.5 ? 'hyperactivity' : '',
    userSignature.qm_core.impulsivity_mean >= 2.5 ? 'impulsivity' : '',
  ].filter(Boolean);

  for (const tag of priorityTags) {
    for (const w of WHISPERS) {
      if (used.has(w.id)) continue;
      if (w.tags.includes(tag)) {
        selected.push(w);
        used.add(w.id);
        if (selected.length >= count) return selected;
        break;
      }
    }
  }

  // 如果还不够，随机补充
  const remaining = WHISPERS.filter((w) => !used.has(w.id));
  const shuffled = remaining.sort(() => Math.random() - 0.5);
  for (const w of shuffled) {
    if (selected.length >= count) break;
    selected.push(w);
    used.add(w.id);
  }

  return selected;
}

export const WHISPER_COUNT = WHISPERS.length;
